import sys,os,collections
sys.path.insert(0,"/root/unitex-finrep/engine"); os.chdir("/root/unitex-finrep")
from odata_client import ODataClient
c=ODataClient()
acc={a["Ref_Key"]:((a.get("Code") or "").strip(),(a.get("Description") or "").strip())
     for a in c.list("ChartOfAccounts_Хозрасчетный", select=["Ref_Key","Code","Description"])}
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
keys={k for k,(code,d) in acc.items() if code in {"1110","1210","1220","1300"}}
NULL="00000000-0000-0000-0000-000000000000"
filled=collections.Counter(); rec=collections.Counter(); tot=0; sample=[]
for r in c.list("AccountingRegister_Хозрасчетный_RecordType"):
    if r.get("AccountDr_Key") not in keys and r.get("AccountCr_Key") not in keys: continue
    if vid.get(r.get("ВидОплаты_Key")): continue      # цікавлять саме БЕЗ виду оплати
    tot+=1
    for k,v in r.items():
        if k.endswith("navigationLinkUrl"): continue
        if k.endswith("_Type") and isinstance(v,str) and "Undefined" not in v: rec[(k,v)]+=1
        if k.endswith("_Key") and isinstance(v,str) and v not in (NULL,) and k not in ("AccountDr_Key","AccountCr_Key","ВидОплаты_Key"):
            filled[k]+=1
    if len(sample)<2: sample.append(r)
print("рухів по грошових рахунках БЕЗ виду оплати:",tot,flush=True)
print("\nякі ознаки заповнені:")
for k,n in filled.most_common(14): print("   %-34s %5d з %d"%(k,n,tot))
print("\nхто реєстратор (документ) цих рухів:")
for (k,v),n in rec.most_common(10): print("   %-22s %-46s %5d"%(k,v,n))
print("\nприклад руху (ненульові поля):")
for r in sample[:1]:
    for k,v in r.items():
        if k.endswith("navigationLinkUrl"): continue
        if v in (None,"",0,False,NULL,"0001-01-01T00:00:00"): continue
        print("   %-32s %s"%(k,str(v)[:52]))
PY
cd /root/direct-sync && nohup /root/unitex-finrep/.venv/bin/python money_dims.py > /root/direct-sync/money_dims.out 2>&1 &
